#!/usr/bin/env node
// Policy as code for the roster agents: model, effort, turn budget, tools and permission mode.
// Reads .claude/agents/*.md front matter and compares it with scripts/governance/agent-policy.json.
//
// Usage: node scripts/governance/check-agent-policy.mjs [--agents-dir .claude/agents] [--policy <file>] [--strict]
// Exit 0 = no violations (missing roster files are warnings unless --strict), 1 = violations.
import { existsSync, readdirSync, readFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { splitFrontmatter, toolList } from "./lib/frontmatter.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const arg = (n, d) => { const i = process.argv.indexOf(`--${n}`); return i > 0 ? process.argv[i + 1] : d; };
const agentsDir = resolve(arg("agents-dir", join(ROOT, ".claude/agents")));
const policy = JSON.parse(readFileSync(resolve(arg("policy", join(ROOT, "scripts/governance/agent-policy.json"))), "utf8"));
const STRICT = process.argv.includes("--strict");

// "claude-opus-5-5" -> "opus"; aliases pass through.
const family = (m) => (/opus/i.test(m) ? "opus" : /sonnet/i.test(m) ? "sonnet" : /haiku/i.test(m) ? "haiku" : /fable/i.test(m) ? "fable" : String(m));
const toolName = (t) => t.replace(/\(.*$/, "");

const errors = [];
const warnings = [];
const rows = [];
const files = existsSync(agentsDir) ? readdirSync(agentsDir).filter((f) => f.endsWith(".md")) : [];
const byName = new Map();
for (const f of files) {
  const { frontmatter } = splitFrontmatter(readFileSync(join(agentsDir, f), "utf8"));
  if (!frontmatter) { errors.push(`${f}: no YAML front matter`); continue; }
  byName.set(frontmatter.name || f.replace(/\.md$/, ""), { file: f, fm: frontmatter });
}

for (const [name, rule] of Object.entries(policy.agents)) {
  const entry = byName.get(name);
  if (!entry) { (STRICT ? errors : warnings).push(`${name}: .claude/agents/${name}.md not found (not written yet?)`); continue; }
  const { file, fm } = entry;
  const tag = `${file}`;
  for (const k of rule.requireFields || policy.global.requireFields) if (fm[k] === undefined || fm[k] === "") errors.push(`${tag}: missing required field "${k}"${k === "tools" ? " (omitted tools = inherits every tool, including MCP write tools)" : ""}`);
  const model = fm.model === undefined ? "" : String(fm.model);
  if (policy.global.forbiddenModels.includes(model)) errors.push(`${tag}: model "${model}" is not allowed (cost and behaviour must not depend on the caller's model)`);
  else if (model && !rule.models.includes(family(model))) errors.push(`${tag}: model "${model}" not in policy [${rule.models.join(", ")}]`);
  if (fm.effort !== undefined && !rule.effort.includes(String(fm.effort))) errors.push(`${tag}: effort "${fm.effort}" not in policy [${rule.effort.join(", ")}]`);
  if (fm.maxTurns !== undefined && !(Number(fm.maxTurns) > 0 && Number(fm.maxTurns) <= rule.maxTurns)) errors.push(`${tag}: maxTurns ${fm.maxTurns} exceeds policy ceiling ${rule.maxTurns}`);
  if (policy.global.forbiddenPermissionModes.includes(fm.permissionMode)) errors.push(`${tag}: permissionMode "${fm.permissionMode}" is forbidden`);
  const tools = toolList(fm.tools) || [];
  const names = tools.map(toolName);
  for (const t of rule.forbiddenTools) if (names.includes(t)) errors.push(`${tag}: tool "${t}" is forbidden for ${name}`);
  if (names.includes(policy.global.delegationTool) && !policy.global.delegationAllowedFor.includes(name)) {
    errors.push(`${tag}: "${policy.global.delegationTool}" in tools lets ${name} spawn subagents; the roster is flat (only ${policy.global.delegationAllowedFor.join(", ")} delegates)`);
  }
  rows.push([name, model || "-", String(fm.effort ?? "-"), String(fm.maxTurns ?? "-"), String(fm.permissionMode ?? "-"), names.join(" ") || "-"]);
}
for (const [name, { file }] of byName) if (!policy.agents[name]) warnings.push(`${file}: agent "${name}" has no policy entry (add it to agent-policy.json)`);

if (rows.length) {
  const head = ["agent", "model", "effort", "maxTurns", "permissionMode", "tools"];
  const w = head.map((h, i) => Math.max(h.length, ...rows.map((r) => r[i].length)));
  const fmt = (r) => r.map((c, i) => c.padEnd(w[i])).join("  ");
  console.log(fmt(head));
  for (const r of rows) console.log(fmt(r));
  console.log("");
}
for (const w of warnings) console.log(`WARN   ${w}`);
for (const e of errors) console.log(`ERROR  ${e}`);
console.log(`\n${rows.length}/${Object.keys(policy.agents).length} roster agents checked, ${errors.length} violation(s), ${warnings.length} warning(s)`);
process.exit(errors.length ? 1 : 0);

#!/usr/bin/env node
// Runs check-agent-policy.mjs against fixture agent folders. Usage: node scripts/governance/check-agent-policy.test.mjs
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const script = join(dirname(fileURLToPath(import.meta.url)), "check-agent-policy.mjs");
const agent = (fm) => `---\n${fm}\n---\n\nYou are a test agent.\n`;
const good = {
  "reviewer.md": agent("name: reviewer\ndescription: Reviews diffs\ntools: Read, Grep, Glob, Bash\nmodel: sonnet\neffort: high\nmaxTurns: 25\npermissionMode: dontAsk"),
  "security.md": agent("name: security\ndescription: Security review\ntools: Read, Grep, Glob\nmodel: claude-opus-5-5\neffort: high\nmaxTurns: 30"),
};
const cases = [
  { name: "compliant agents pass", files: good, expect: 0, grep: /0 violation\(s\)/ },
  { name: "reviewer with Edit is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("tools: Read,", "tools: Read, Edit,") }, expect: 1, grep: /tool "Edit" is forbidden for reviewer/ },
  { name: "omitted tools is a violation", files: { ...good, "security.md": good["security.md"].replace("tools: Read, Grep, Glob\n", "") }, expect: 1, grep: /missing required field "tools"/ },
  { name: "model inherit is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("model: sonnet", "model: inherit") }, expect: 1, grep: /model "inherit" is not allowed/ },
  { name: "maxTurns above ceiling is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("maxTurns: 25", "maxTurns: 200") }, expect: 1, grep: /maxTurns 200 exceeds policy ceiling 25/ },
  { name: "bypassPermissions is a violation", files: { ...good, "security.md": good["security.md"].replace("maxTurns: 30", "maxTurns: 30\npermissionMode: bypassPermissions") }, expect: 1, grep: /permissionMode "bypassPermissions" is forbidden/ },
  { name: "non-orchestrator with Agent is a violation", files: { ...good, "reviewer.md": good["reviewer.md"].replace("Bash\n", "Bash, Agent\n") }, expect: 1, grep: /"Agent" in tools lets reviewer spawn subagents/ },
  { name: "missing roster file fails only with --strict", files: good, args: ["--strict"], expect: 1, grep: /architect: .*not found/ },
];

let failed = 0;
for (const c of cases) {
  const dir = mkdtempSync(join(tmpdir(), "agent-policy-"));
  mkdirSync(join(dir, "agents"));
  for (const [f, body] of Object.entries(c.files)) writeFileSync(join(dir, "agents", f), body);
  const r = spawnSync(process.execPath, [script, "--agents-dir", join(dir, "agents"), ...(c.args || [])], { encoding: "utf8" });
  const ok = r.status === c.expect && c.grep.test(r.stdout);
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${c.name} (exit ${r.status}, expected ${c.expect})${ok ? "" : "\n" + r.stdout}`);
}
console.log(`\n${cases.length - failed}/${cases.length} passed`);
process.exit(failed ? 1 : 0);

#!/usr/bin/env node
// Aggregate the cost of a workflow run from saved `claude -p --output-format json` results and
// enforce a run-level budget.
//
// Each step of a headless run saves its result JSON (fields used: total_cost_usd, num_turns,
// subtype, is_error, duration_ms, session_id, modelUsage) as <run-dir>/costs/NN-<agent>.json:
//   claude -p "$PROMPT" --agent reviewer --max-turns 25 --max-budget-usd 2.00 \
//     --output-format json > .ai-sdlc/runs/$RUN_ID/costs/03-reviewer.json
//
// Usage: node scripts/governance/cost-report.mjs <run-dir>/costs [--budget-usd 10] [--json]
// Exit 0 = within budget and no step hit a limit, 1 = over budget or a step stopped on a limit,
// 2 = usage error. total_cost_usd is a client-side estimate; reconcile monthly with billing.
import { readdirSync, readFileSync } from "node:fs";
import { basename, join } from "node:path";

const dir = process.argv[2];
if (!dir || dir.startsWith("--")) {
  console.error("usage: cost-report.mjs <costs-dir> [--budget-usd N] [--json]");
  process.exit(2);
}
const i = process.argv.indexOf("--budget-usd");
const budget = i > 0 ? Number(process.argv[i + 1]) : null;
const LIMIT_SUBTYPES = new Set(["error_max_turns", "error_max_budget_usd"]);

const steps = [];
for (const f of readdirSync(dir).filter((x) => x.endsWith(".json")).sort()) {
  let r;
  try { r = JSON.parse(readFileSync(join(dir, f), "utf8")); } catch (e) { steps.push({ file: f, agent: "?", error: `invalid JSON: ${e.message}` }); continue; }
  const m = /^(\d+)-(.+)\.json$/.exec(basename(f));
  steps.push({
    file: f,
    step: m ? m[1] : "",
    agent: m ? m[2] : basename(f, ".json"),
    cost: Number(r.total_cost_usd ?? 0),
    turns: Number(r.num_turns ?? 0),
    subtype: String(r.subtype ?? "unknown"),
    isError: Boolean(r.is_error),
    seconds: r.duration_ms != null ? Math.round(Number(r.duration_ms) / 1000) : null,
    models: r.modelUsage && typeof r.modelUsage === "object" ? Object.keys(r.modelUsage) : [],
  });
}

const total = steps.reduce((s, x) => s + (x.cost || 0), 0);
const problems = [];
for (const s of steps) {
  if (s.error) problems.push(`${s.file}: ${s.error}`);
  else if (LIMIT_SUBTYPES.has(s.subtype)) problems.push(`${s.file}: stopped on a limit (${s.subtype}); output is partial, a human must decide whether to resume or re-plan`);
  else if (s.isError) problems.push(`${s.file}: is_error=true (subtype ${s.subtype})`);
}
if (budget != null && total > budget) problems.push(`run total $${total.toFixed(2)} exceeds budget $${budget.toFixed(2)}`);

if (process.argv.includes("--json")) {
  console.log(JSON.stringify({ total_cost_usd: Number(total.toFixed(4)), budget_usd: budget, steps, problems }, null, 2));
} else {
  const rows = steps.map((s) => [s.step, s.agent, s.error ? "-" : `$${s.cost.toFixed(2)}`, String(s.turns ?? "-"), s.subtype ?? "-", s.models.join(",") || "-"]);
  const head = ["step", "agent", "cost", "turns", "subtype", "models"];
  const w = head.map((h, k) => Math.max(h.length, ...rows.map((r) => r[k].length)));
  const fmt = (r) => r.map((c, k) => c.padEnd(w[k])).join("  ");
  console.log(fmt(head));
  for (const r of rows) console.log(fmt(r));
  const share = steps.filter((s) => s.cost).sort((a, b) => b.cost - a.cost)[0];
  console.log(`\nTotal: $${total.toFixed(2)}${budget != null ? ` of $${budget.toFixed(2)} budget (${Math.round((total / budget) * 100)}%)` : ""}`);
  if (share && total > 0) console.log(`Largest step: ${share.step}-${share.agent} ($${share.cost.toFixed(2)}, ${Math.round((share.cost / total) * 100)}% of run)`);
  for (const p of problems) console.log(`PROBLEM  ${p}`);
}
process.exit(problems.length ? 1 : 0);

#!/usr/bin/env node
// Runs cost-report.mjs against fixture result files shaped like `claude -p --output-format json` output.
// Usage: node scripts/governance/cost-report.test.mjs
import { spawnSync } from "node:child_process";
import { mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const script = join(dirname(fileURLToPath(import.meta.url)), "cost-report.mjs");
const result = (o) => JSON.stringify({ type: "result", subtype: "success", is_error: false, duration_ms: 61000, num_turns: 9, session_id: "3f0c9b1e-0000-4000-8000-000000000001", result: "done", total_cost_usd: 0.5, usage: {}, modelUsage: { "claude-sonnet-5": {} }, ...o });
function run(files, args = []) {
  const dir = mkdtempSync(join(tmpdir(), "costs-"));
  for (const [f, body] of Object.entries(files)) writeFileSync(join(dir, f), body);
  return spawnSync(process.execPath, [script, dir, ...args], { encoding: "utf8" });
}
const feature = {
  "02-architect.json": result({ total_cost_usd: 1.84, num_turns: 14, modelUsage: { "claude-opus-5-5": {} } }),
  "04-developer.json": result({ total_cost_usd: 2.31, num_turns: 31 }),
  "05-tester.json": result({ total_cost_usd: 0.92, num_turns: 12 }),
  "06-reviewer.json": result({ total_cost_usd: 0.61, num_turns: 8 }),
  "07-security.json": result({ total_cost_usd: 1.12, num_turns: 10, modelUsage: { "claude-opus-5-5": {} } }),
};
const cases = [
  { name: "feature run within budget passes", files: feature, args: ["--budget-usd", "10"], expect: 0, grep: /Total: \$6\.80 of \$10\.00 budget \(68%\)/ },
  { name: "same run over a $5 budget fails", files: feature, args: ["--budget-usd", "5"], expect: 1, grep: /run total \$6\.80 exceeds budget \$5\.00/ },
  { name: "step that hit --max-turns fails the run", files: { ...feature, "04-developer.json": result({ subtype: "error_max_turns", is_error: true, total_cost_usd: 3.9, num_turns: 60 }) }, args: [], expect: 1, grep: /04-developer\.json: stopped on a limit \(error_max_turns\)/ },
  { name: "step that hit --max-budget-usd fails the run", files: { "06-reviewer.json": result({ subtype: "error_max_budget_usd", is_error: true, total_cost_usd: 2.0 }) }, args: [], expect: 1, grep: /error_max_budget_usd/ },
  { name: "largest step is reported", files: feature, args: [], expect: 0, grep: /Largest step: 04-developer \(\$2\.31, 34% of run\)/ },
  { name: "json output is machine-readable", files: feature, args: ["--json", "--budget-usd", "10"], expect: 0, grep: /"total_cost_usd": 6\.8/ },
];
let failed = 0;
for (const c of cases) {
  const r = run(c.files, c.args);
  const ok = r.status === c.expect && c.grep.test(r.stdout);
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${c.name} (exit ${r.status}, expected ${c.expect})${ok ? "" : "\n" + r.stdout + r.stderr}`);
}
console.log(`\n${cases.length - failed}/${cases.length} passed`);
process.exit(failed ? 1 : 0);

// Minimal YAML front matter reader for agent and skill Markdown files (zero dependencies).
// Supports what Claude Code agent/skill files use at the top level: `key: scalar`, quoted
// scalars, inline lists `[a, b]`, block lists (`key:` followed by `  - item`), and folded
// or literal blocks (`key: >` / `key: |`). Nested maps such as `hooks:` are kept as raw text.

export function splitFrontmatter(text) {
  const src = text.replace(/^\uFEFF/, "").replace(/\r\n/g, "\n");
  if (!src.startsWith("---\n")) return { frontmatter: null, body: src, raw: "" };
  const end = src.indexOf("\n---", 4);
  if (end < 0) return { frontmatter: null, body: src, raw: "", error: "unterminated front matter" };
  const raw = src.slice(4, end);
  const after = src.indexOf("\n", end + 4);
  const body = after < 0 ? "" : src.slice(after + 1);
  return { frontmatter: parse(raw), body, raw };
}

function unquote(v) {
  const t = v.trim();
  if ((t.startsWith('"') && t.endsWith('"')) || (t.startsWith("'") && t.endsWith("'"))) return t.slice(1, -1);
  return t;
}

function scalar(v) {
  const t = unquote(v);
  if (/^\[.*\]$/.test(v.trim())) {
    return v.trim().slice(1, -1).split(",").map((s) => unquote(s)).filter(Boolean);
  }
  if (/^(true|yes|on)$/i.test(t) && t === v.trim()) return true;
  if (/^(false|no|off)$/i.test(t) && t === v.trim()) return false;
  if (/^-?\d+$/.test(t) && t === v.trim()) return Number(t);
  return t;
}

export function parse(raw) {
  const out = {};
  const lines = raw.split("\n");
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i];
    const m = /^([A-Za-z_][A-Za-z0-9_-]*):(?:\s+(.*))?$/.exec(line);
    if (!m) continue;
    const [, key, rest = ""] = m;
    const value = rest.replace(/\s+#.*$/, "");
    if (value === ">" || value === "|" || value === ">-" || value === "|-") {
      const block = [];
      while (i + 1 < lines.length && (/^\s+/.test(lines[i + 1]) || lines[i + 1] === "")) block.push(lines[++i].trim());
      out[key] = value.startsWith(">") ? block.join(" ").trim() : block.join("\n").trim();
    } else if (value === "") {
      const items = [];
      const nested = [];
      while (i + 1 < lines.length && (/^\s+/.test(lines[i + 1]) || lines[i + 1] === "")) {
        const l = lines[++i];
        nested.push(l);
        const li = /^\s+-\s+(.*)$/.exec(l);
        if (li && /^\s{0,4}-/.test(l)) items.push(scalar(li[1]));
      }
      const isList = nested.filter((l) => l.trim()).every((l) => /^\s{0,4}-\s/.test(l) || /^\s{4,}/.test(l)) && items.length;
      out[key] = isList ? items : nested.join("\n");
    } else {
      out[key] = scalar(value);
    }
  }
  return out;
}

// "Read, Grep, Bash(git diff *)" or a YAML list -> ["Read", "Grep", "Bash(git diff *)"]
export function toolList(v) {
  if (v == null) return null;
  if (Array.isArray(v)) return v.map(String);
  const s = String(v);
  const out = [];
  let depth = 0;
  let cur = "";
  for (const ch of s) {
    if (ch === "(") depth++;
    if (ch === ")") depth--;
    if ((ch === "," || ch === " ") && depth === 0) {
      if (cur.trim()) out.push(cur.trim());
      cur = "";
    } else cur += ch;
  }
  if (cur.trim()) out.push(cur.trim());
  return out;
}

#!/usr/bin/env node
// Validate the skill library: runtime skills (.claude/skills/<name>/SKILL.md) and their
// engineering assets (skills/<name>/README.md, CHANGELOG.md, tests/cases.json).
// Policy: skills/README.md.
//
// Usage: node scripts/governance/validate-skill-library.mjs [--root <AI-SDLC dir>] [--strict] [--json]
// Exit 0 = no errors (warnings allowed unless --strict), 1 = errors.
import { existsSync, readdirSync, readFileSync, statSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { splitFrontmatter } from "./lib/frontmatter.mjs";

const arg = (n, d) => { const i = process.argv.indexOf(`--${n}`); return i > 0 ? process.argv[i + 1] : d; };
const ROOT = resolve(arg("root", resolve(dirname(fileURLToPath(import.meta.url)), "../..")));
const STRICT = process.argv.includes("--strict");

// Skill frontmatter keys documented by Claude Code (skills docs). Anything else is silently
// ignored by Claude Code, which is exactly why a typo such as `allowedTools` must be reported.
const KNOWN_KEYS = new Set([
  "name", "description", "when_to_use", "argument-hint", "arguments", "disable-model-invocation",
  "user-invocable", "allowed-tools", "disallowed-tools", "model", "effort", "context", "agent",
  "background", "hooks", "paths", "shell", "metadata", "license", "compatibility",
]);
// Keys accepted by claude.ai uploads / the Skills API; anything else there is a hard error.
const PORTABLE_KEYS = new Set(["name", "description", "license", "compatibility", "metadata", "allowed-tools"]);
const SEMVER = /^##\s+\[?v?(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)\]?(?:\s|$)/m;
const SEMVER_ALL = /^##\s+\[?v?(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)\]?(?:\s|$)/gm;

const findings = []; // {level, skill, message}
const add = (level, skill, message) => findings.push({ level, skill, message });
const dirs = (p) => (existsSync(p) ? readdirSync(p).filter((d) => statSync(join(p, d)).isDirectory()).sort() : []);

const runtimeDir = join(ROOT, ".claude/skills");
const libraryDir = join(ROOT, "skills");
const runtime = dirs(runtimeDir);
const library = dirs(libraryDir);
const rows = new Map();
const row = (name) => rows.get(name) || rows.set(name, { name, skillMd: "-", version: "-", owner: "-", tests: "-", portable: "-" }).get(name);

// 1. Runtime skills
for (const name of runtime) {
  const r = row(name);
  const file = join(runtimeDir, name, "SKILL.md");
  if (!existsSync(file)) { add("error", name, `.claude/skills/${name}/ has no SKILL.md (work in progress, or remove the folder)`); r.skillMd = "missing"; continue; }
  const text = readFileSync(file, "utf8");
  const { frontmatter: fm, error } = splitFrontmatter(text);
  if (!fm) { add("error", name, `SKILL.md has no YAML front matter${error ? ` (${error})` : ""}`); r.skillMd = "no-frontmatter"; continue; }
  r.skillMd = "ok";
  if (!fm.name) add("error", name, "SKILL.md front matter is missing `name` (library policy requires it even though Claude Code defaults it to the folder name)");
  else {
    if (!/^[a-z0-9]+(-[a-z0-9]+)*$/.test(String(fm.name))) add("error", name, `name "${fm.name}" must be lowercase kebab-case (no ":" or spaces)`);
    if (String(fm.name) !== name) add("warn", name, `name "${fm.name}" differs from folder "${name}"; the slash command becomes /${fm.name}`);
  }
  if (!fm.description) add("error", name, "SKILL.md front matter is missing `description` (Claude uses it to decide when to load the skill)");
  else {
    const len = String(fm.description).length + String(fm.when_to_use || "").length;
    if (len > 1536) add("warn", name, `description + when_to_use is ${len} chars; the skill listing truncates at 1,536`);
    if (String(fm.description).length < 40) add("warn", name, "description is under 40 chars; say what the skill does AND when to use it");
  }
  const keys = Object.keys(fm);
  for (const k of keys) if (!KNOWN_KEYS.has(k)) add("warn", name, `unknown front matter key "${k}" is silently ignored by Claude Code${/[A-Z]/.test(k) ? " (skill keys are hyphenated, e.g. allowed-tools)" : ""}`);
  r.portable = keys.every((k) => PORTABLE_KEYS.has(k)) ? "yes" : "no";
  const lines = text.split("\n").length;
  if (lines > 500) add("warn", name, `SKILL.md is ${lines} lines; keep it under 500 and move reference material to supporting files`);
  if (fm["disable-model-invocation"] === true && fm["user-invocable"] === false) add("error", name, "disable-model-invocation: true and user-invocable: false make the skill unreachable");
  if (!library.includes(name)) add("warn", name, `not in the library: add skills/${name}/ with README.md, CHANGELOG.md and tests/cases.json`);
}

// 1b. Plugin-native skills (company-ai/skills/<name>/SKILL.md): same front matter rules.
const pluginSkillsDir = join(ROOT, "company-ai/skills");
for (const name of dirs(pluginSkillsDir)) {
  const file = join(pluginSkillsDir, name, "SKILL.md");
  const tag = `company-ai:${name}`;
  if (!existsSync(file)) { add("error", tag, `company-ai/skills/${name}/ has no SKILL.md`); continue; }
  const { frontmatter: fm } = splitFrontmatter(readFileSync(file, "utf8"));
  if (!fm?.name) add("error", tag, "SKILL.md front matter is missing `name`");
  if (!fm?.description) add("error", tag, "SKILL.md front matter is missing `description`");
  for (const k of Object.keys(fm || {})) if (!KNOWN_KEYS.has(k)) add("warn", tag, `unknown front matter key "${k}" is silently ignored by Claude Code`);
}

// 2. Library assets
const indexText = existsSync(join(libraryDir, "README.md")) ? readFileSync(join(libraryDir, "README.md"), "utf8") : "";
if (!indexText) add("error", "(library)", "skills/README.md (library index and policy) is missing");
for (const name of library) {
  const r = row(name);
  const base = join(libraryDir, name);
  if (!runtime.includes(name)) add("error", name, `skills/${name}/ has no runtime skill at .claude/skills/${name}/SKILL.md`);
  const readmeFile = join(base, "README.md");
  const changelogFile = join(base, "CHANGELOG.md");
  let readmeVersion = null;
  if (!existsSync(readmeFile)) add("error", name, `skills/${name}/README.md is missing`);
  else {
    const readme = readFileSync(readmeFile, "utf8");
    const owner = /\bowner\b[*_]*\s*[:|]\s*[*_]*\s*([^|*\n(]+)/i.exec(readme);
    const version = /\bversion\b[*_]*\s*[:|]\s*[*_`]*\s*v?(\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?)/i.exec(readme);
    if (owner && owner[1].trim()) r.owner = owner[1].trim().replace(/,.*$/, "").slice(0, 28); else add("warn", name, "README.md does not declare an Owner (e.g. `Owner: @example-org/fhir-platform`)");
    if (version) readmeVersion = version[1]; else add("warn", name, "README.md does not declare a Version (e.g. `Version: 1.0.0`)");
  }
  if (!existsSync(changelogFile)) add("error", name, `skills/${name}/CHANGELOG.md is missing`);
  else {
    const cl = readFileSync(changelogFile, "utf8");
    const m = SEMVER.exec(cl);
    if (!m) add("error", name, "CHANGELOG.md has no semver heading (expected e.g. `## [1.0.0] - 2026-09-30`)");
    else {
      r.version = m[1];
      if (readmeVersion && readmeVersion !== m[1]) add("error", name, `README.md says Version ${readmeVersion} but the latest CHANGELOG.md entry is ${m[1]}`);
      const all = [...cl.matchAll(SEMVER_ALL)].map((x) => x[1].split("-")[0].split(".").map(Number));
      for (let i = 1; i < all.length; i++) {
        const [a, b] = [all[i - 1], all[i]];
        const newer = a[0] - b[0] || a[1] - b[1] || a[2] - b[2];
        if (newer <= 0) { add("warn", name, `CHANGELOG.md versions are not in descending order (${a.join(".")} before ${b.join(".")})`); break; }
      }
    }
  }
  const casesFile = join(base, "tests/cases.json");
  if (!existsSync(casesFile)) { add("warn", name, `skills/${name}/tests/cases.json is missing (golden cases for the skill)`); r.tests = "missing"; }
  else {
    try {
      const data = JSON.parse(readFileSync(casesFile, "utf8"));
      const n = Array.isArray(data) ? data.length : Array.isArray(data.cases) ? data.cases.length : 0;
      r.tests = String(n);
      if (n < 3) add("warn", name, `tests/cases.json has ${n} case(s); the policy asks for at least 3`);
    } catch (e) {
      add("error", name, `tests/cases.json is not valid JSON: ${e.message}`);
      r.tests = "invalid";
    }
  }
  if (indexText && !indexText.includes(`\`${name}\``) && !indexText.includes(`skills/${name}/`)) add("warn", name, "not listed in the skills/README.md index");
}

const errors = findings.filter((f) => f.level === "error");
const warns = findings.filter((f) => f.level === "warn");
if (process.argv.includes("--json")) {
  console.log(JSON.stringify({ root: ROOT, skills: [...rows.values()], findings }, null, 2));
} else {
  const head = ["skill", "SKILL.md", "version", "owner", "tests", "portable"];
  const data = [...rows.values()].sort((a, b) => a.name.localeCompare(b.name)).map((r) => [r.name, r.skillMd, r.version, r.owner, r.tests, r.portable]);
  const w = head.map((h, i) => Math.max(h.length, ...data.map((d) => d[i].length)));
  const fmt = (r) => r.map((c, i) => c.padEnd(w[i])).join("  ");
  console.log(`Skill library report for ${ROOT}\n`);
  console.log(fmt(head));
  for (const d of data) console.log(fmt(d));
  console.log("");
  for (const f of [...errors, ...warns]) console.log(`${f.level === "error" ? "ERROR" : "WARN "}  ${f.skill}: ${f.message}`);
  console.log(`\n${runtime.length} runtime skill(s), ${library.length} library entr${library.length === 1 ? "y" : "ies"}: ${errors.length} error(s), ${warns.length} warning(s)`);
}
process.exit(errors.length || (STRICT && warns.length) ? 1 : 0);

#!/usr/bin/env node
// Runs validate-skill-library.mjs against fixture repositories built in a temp dir.
// Usage: node scripts/governance/validate-skill-library.test.mjs
import { spawnSync } from "node:child_process";
import { mkdirSync, mkdtempSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const script = join(dirname(fileURLToPath(import.meta.url)), "validate-skill-library.mjs");
const SKILL = "---\nname: code-review\ndescription: Review a git diff against context/standards and return findings in the canonical format.\nallowed-tools: Read Grep Glob Bash(git diff *)\n---\n\nReview $ARGUMENTS.\n";
const README = "# code-review\n\n| Field | Value |\n|---|---|\n| Owner | @example-org/fhir-platform |\n| Version | 1.1.0 |\n";
const CHANGELOG = "# Changelog\n\n## [1.1.0] - 2026-09-30\n### Added\n- 401/403 test check.\n\n## [1.0.0] - 2026-09-01\n### Added\n- Initial release.\n";
const CASES = JSON.stringify({ cases: [{ id: "cr-1" }, { id: "cr-2" }, { id: "cr-3" }] });
const INDEX = "# Skill library\n\n| Skill | Owner |\n|---|---|\n| `code-review` | @example-org/fhir-platform |\n";

function repo(files) {
  const root = mkdtempSync(join(tmpdir(), "skill-lib-"));
  for (const [p, body] of Object.entries(files)) {
    if (body == null) continue;
    mkdirSync(dirname(join(root, p)), { recursive: true });
    writeFileSync(join(root, p), body);
  }
  return root;
}
const good = {
  ".claude/skills/code-review/SKILL.md": SKILL,
  "skills/README.md": INDEX,
  "skills/code-review/README.md": README,
  "skills/code-review/CHANGELOG.md": CHANGELOG,
  "skills/code-review/tests/cases.json": CASES,
};
const cases = [
  { name: "complete skill passes with no warnings", files: good, args: ["--strict"], expect: 0, grep: /0 error\(s\), 0 warning\(s\)/ },
  { name: "missing description is an error", files: { ...good, ".claude/skills/code-review/SKILL.md": SKILL.replace(/description:.*\n/, "") }, expect: 1, grep: /missing `description`/ },
  { name: "missing name is an error", files: { ...good, ".claude/skills/code-review/SKILL.md": SKILL.replace("name: code-review\n", "") }, expect: 1, grep: /missing `name`/ },
  { name: "CHANGELOG without semver heading is an error", files: { ...good, "skills/code-review/CHANGELOG.md": "# Changelog\n\n## Latest\n- stuff\n" }, expect: 1, grep: /no semver heading/ },
  { name: "README version must match latest CHANGELOG entry", files: { ...good, "skills/code-review/README.md": README.replace("1.1.0", "1.0.0") }, expect: 1, grep: /README\.md says Version 1\.0\.0 but the latest CHANGELOG\.md entry is 1\.1\.0/ },
  { name: "missing README is an error", files: { ...good, "skills/code-review/README.md": null }, expect: 1, grep: /skills\/code-review\/README\.md is missing/ },
  { name: "camelCase key is reported as silently ignored", files: { ...good, ".claude/skills/code-review/SKILL.md": SKILL.replace("allowed-tools:", "allowedTools:") }, args: ["--strict"], expect: 1, grep: /unknown front matter key "allowedTools".*hyphenated/ },
  { name: "runtime skill outside the library is a warning only", files: { ...good, ".claude/skills/run-tests/SKILL.md": SKILL.replace(/code-review/g, "run-tests") }, expect: 0, grep: /WARN\s+run-tests: not in the library/ },
  { name: "library entry without runtime skill is an error", files: { ...good, "skills/orphan/README.md": README, "skills/orphan/CHANGELOG.md": CHANGELOG }, expect: 1, grep: /skills\/orphan\/ has no runtime skill/ },
  { name: "invalid cases.json is an error", files: { ...good, "skills/code-review/tests/cases.json": "{ not json" }, expect: 1, grep: /tests\/cases\.json is not valid JSON/ },
];

let failed = 0;
for (const c of cases) {
  const r = spawnSync(process.execPath, [script, "--root", repo(c.files), ...(c.args || [])], { encoding: "utf8" });
  const ok = r.status === c.expect && c.grep.test(r.stdout);
  if (!ok) failed++;
  console.log(`${ok ? "PASS" : "FAIL"}  ${c.name} (exit ${r.status}, expected ${c.expect})${ok ? "" : "\n" + r.stdout + r.stderr}`);
}
console.log(`\n${cases.length - failed}/${cases.length} passed`);
process.exit(failed ? 1 : 0);

#!/usr/bin/env node
// Package library skills (and optionally roster agents) from this repository into the company-ai
// Claude Code plugin. Source of truth stays in .claude/skills/ and skills/; the plugin is a build
// output that other repositories install.
//
// Usage:
//   node scripts/governance/package-plugin.mjs --out <dir> [--skills a,b] [--agents x,y] [--version 0.2.0]
//   --skills  default: every skill with skills/<name>/CHANGELOG.md (i.e. released library skills)
//   --agents  default: none. Plugin agents IGNORE permissionMode, hooks and mcpServers, so an agent
//             that relies on them loses those controls when shipped in a plugin; this script warns.
// Then: claude plugin validate <dir>   and   claude --plugin-dir <dir>
import { cpSync, existsSync, mkdirSync, readdirSync, readFileSync, rmSync, statSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { splitFrontmatter } from "./lib/frontmatter.mjs";

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), "../..");
const arg = (n) => { const i = process.argv.indexOf(`--${n}`); return i > 0 ? process.argv[i + 1] : undefined; };
const outArg = arg("out");
if (!outArg) { console.error("usage: package-plugin.mjs --out <dir> [--skills a,b] [--agents x,y] [--version x.y.z]"); process.exit(2); }
const OUT = resolve(outArg);
if (OUT === ROOT || OUT === join(ROOT, "company-ai") || ROOT.startsWith(OUT + "/")) { console.error("refusing to write into the repository source tree; choose a build directory"); process.exit(2); }

const list = (v) => (v ? v.split(",").map((s) => s.trim()).filter(Boolean) : null);
const released = existsSync(join(ROOT, "skills"))
  ? readdirSync(join(ROOT, "skills")).filter((d) => existsSync(join(ROOT, "skills", d, "CHANGELOG.md")))
  : [];
const skills = list(arg("skills")) || released;
const agents = list(arg("agents")) || [];
const warnings = [];
const errors = [];

rmSync(OUT, { recursive: true, force: true });
mkdirSync(OUT, { recursive: true });
// 1. Plugin skeleton: manifest, README, CHANGELOG, plugin-native skills.
cpSync(join(ROOT, "company-ai"), OUT, { recursive: true });

// 2. Library skills: runtime folder + the library CHANGELOG/README travel with the skill.
const packaged = [];
for (const name of skills) {
  const src = join(ROOT, ".claude/skills", name);
  if (!existsSync(join(src, "SKILL.md"))) { errors.push(`skill ${name}: .claude/skills/${name}/SKILL.md not found`); continue; }
  const text = readFileSync(join(src, "SKILL.md"), "utf8");
  const { frontmatter: fm } = splitFrontmatter(text);
  if (!fm?.name || !fm?.description) { errors.push(`skill ${name}: SKILL.md needs name and description`); continue; }
  if (/(^|[\s`"'(])\.claude\/skills\//.test(text)) {
    warnings.push(`skill ${name}: SKILL.md uses project-relative paths (.claude/skills/...). In a plugin use \${CLAUDE_SKILL_DIR} or \${CLAUDE_PLUGIN_ROOT} instead.`);
  }
  if (/scripts\/(automation|governance)\//.test(text)) warnings.push(`skill ${name}: depends on repository scripts (scripts/...) that are not shipped in the plugin.`);
  const dest = join(OUT, "skills", name);
  cpSync(src, dest, { recursive: true });
  for (const f of ["README.md", "CHANGELOG.md"]) {
    const p = join(ROOT, "skills", name, f);
    if (existsSync(p)) cpSync(p, join(dest, `LIBRARY-${f}`));
  }
  const cl = existsSync(join(ROOT, "skills", name, "CHANGELOG.md")) ? readFileSync(join(ROOT, "skills", name, "CHANGELOG.md"), "utf8") : "";
  const v = /^##\s+\[?v?(\d+\.\d+\.\d+[^\]\s]*)\]?/m.exec(cl);
  packaged.push(`${name}@${v ? v[1] : "unreleased"}`);
}

// 3. Agents (opt-in).
for (const name of agents) {
  const src = join(ROOT, ".claude/agents", `${name}.md`);
  if (!existsSync(src)) { errors.push(`agent ${name}: .claude/agents/${name}.md not found`); continue; }
  const { frontmatter: fm } = splitFrontmatter(readFileSync(src, "utf8"));
  const dropped = ["permissionMode", "hooks", "mcpServers", "initialPrompt"].filter((k) => fm && fm[k] !== undefined);
  if (dropped.length) warnings.push(`agent ${name}: plugin agents ignore ${dropped.join(", ")}; the packaged agent runs WITHOUT those controls. Enforce them with the consumer's settings.json instead.`);
  mkdirSync(join(OUT, "agents"), { recursive: true });
  cpSync(src, join(OUT, "agents", `${name}.md`));
}

// 4. Bundle the validator so skill-library-check works in any repository.
mkdirSync(join(OUT, "scripts/lib"), { recursive: true });
cpSync(join(ROOT, "scripts/governance/validate-skill-library.mjs"), join(OUT, "scripts/validate-skill-library.mjs"));
cpSync(join(ROOT, "scripts/governance/lib/frontmatter.mjs"), join(OUT, "scripts/lib/frontmatter.mjs"));

// 5. Version stamp.
const manifestPath = join(OUT, ".claude-plugin/plugin.json");
const manifest = JSON.parse(readFileSync(manifestPath, "utf8"));
const version = arg("version");
if (version) {
  if (!/^\d+\.\d+\.\d+(-[0-9A-Za-z.-]+)?$/.test(version)) { console.error(`--version ${version} is not semver`); process.exit(2); }
  manifest.version = version;
}
writeFileSync(manifestPath, JSON.stringify(manifest, null, 2) + "\n");

const count = (d) => (existsSync(join(OUT, d)) ? readdirSync(join(OUT, d)).filter((x) => !x.startsWith(".") && (statSync(join(OUT, d, x)).isDirectory() || x.endsWith(".md"))).length : 0);
console.log(`Packaged ${manifest.name}@${manifest.version} into ${OUT}`);
console.log(`  skills: ${count("skills")} (${["skill-library-check (plugin-native)", ...packaged].join(", ")})`);
console.log(`  agents: ${count("agents")}${agents.length ? ` (${agents.join(", ")})` : ""}`);
for (const w of warnings) console.log(`WARN   ${w}`);
for (const e of errors) console.log(`ERROR  ${e}`);
console.log(`Next: claude plugin validate ${outArg}   then   claude --plugin-dir ${outArg}`);
process.exit(errors.length ? 1 : 0);
